using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(int count = 1) =>
        Enumerable.Range(1, count)
            .Select(i => new OrderItem
            {
                ProductName = $"Product {i}",
                Price = 10m * i,
                Quantity = i
            })
            .ToList();

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectProperties()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 25.00m, Quantity = 2 }
        };

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(50.00m, order.Total);
        Assert.HasCount(1, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithMultipleItems_CalculatesTotalCorrectly()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "A", Price = 10m, Quantity = 2 },
            new() { ProductName = "B", Price = 5m, Quantity = 3 }
        };

        // Act
        var order = _sut.CreateOrder("cust-2", items);

        // Assert — Total = (10*2) + (5*3) = 35
        Assert.AreEqual(35m, order.Total);
    }

    [TestMethod]
    public void CreateOrder_GeneratesUniqueId()
    {
        // Arrange
        var items = CreateItems();

        // Act
        var order1 = _sut.CreateOrder("cust-1", items);
        var order2 = _sut.CreateOrder("cust-1", items);

        // Assert
        Assert.AreNotEqual(order1.Id, order2.Id);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var before = DateTime.UtcNow;
        var items = CreateItems();

        // Act
        var order = _sut.CreateOrder("cust-1", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
    }

    [TestMethod]
    public void CreateOrder_NullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateItems();

        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder(null!, items));

        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_NullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder("cust-1", null!));

        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_EmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("cust-1", []));

        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    [TestMethod]
    public void GetOrder_ExistingOrder_ReturnsOrder()
    {
        // Arrange
        var items = CreateItems();
        var created = _sut.CreateOrder("cust-1", items);

        // Act
        var retrieved = _sut.GetOrder(created.Id);

        // Assert
        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_NonExistentId_ReturnsNull()
    {
        var result = _sut.GetOrder("non-existent-id");

        Assert.IsNull(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        // Arrange
        var items = CreateItems();
        _sut.CreateOrder("cust-A", items);
        _sut.CreateOrder("cust-A", items);
        _sut.CreateOrder("cust-B", items);

        // Act
        var results = _sut.GetOrdersByCustomer("cust-A");

        // Assert
        Assert.HasCount(2, results);
    }

    [TestMethod]
    public void GetOrdersByCustomer_NoOrders_ReturnsEmptyList()
    {
        var results = _sut.GetOrdersByCustomer("unknown");

        Assert.IsEmpty(results);
    }
}

using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _sut;

    public PriceCalculatorTests()
    {
        _sut = new PriceCalculator();
    }

    [TestMethod]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "10% tax")]
    [DataRow(5.00, 3, 0.0, 15.00, DisplayName = "No tax")]
    [DataRow(100.00, 1, 0.25, 125.00, DisplayName = "25% tax")]
    [DataRow(0.00, 5, 0.10, 0.00, DisplayName = "Zero price")]
    public void CalculateTotal_ReturnsExpectedAmount(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _sut.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, -1, 0.1m));

        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_NegativeUnitPrice_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(-5m, 1, 0.1m));

        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Below zero")]
    [DataRow(1.01, DisplayName = "Above 1")]
    public void CalculateTotal_InvalidTaxRate_ThrowsArgumentOutOfRangeException(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, 1, (decimal)taxRate));

        Assert.AreEqual("taxRate", ex.ParamName);
    }

    [TestMethod]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(200.00, 50.0, 100.00, DisplayName = "50% off")]
    [DataRow(80.00, 0.0, 80.00, DisplayName = "No discount")]
    [DataRow(80.00, 100.0, 0.00, DisplayName = "100% off")]
    public void ApplyDiscount_ReturnsExpectedPrice(
        double price, double discountPercent, double expected)
    {
        var result = _sut.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(100.01, DisplayName = "Over 100%")]
    public void ApplyDiscount_InvalidPercent_ThrowsArgumentOutOfRangeException(double discount)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.ApplyDiscount(50m, (decimal)discount));
    }

    [TestMethod]
    public void FormatPrice_DefaultCurrency_ReturnsDollarFormat()
    {
        var result = _sut.FormatPrice(19.99m);

        Assert.AreEqual("$19.99", result);
    }

    [TestMethod]
    [DataRow("€", 9.99, "€9.99")]
    [DataRow("£", 100.00, "£100.00")]
    public void FormatPrice_CustomCurrency_ReturnsCorrectFormat(
        string symbol, double price, string expected)
    {
        var result = _sut.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

